CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY, shop_name TEXT NOT NULL DEFAULT 'Coffee Shop', currency_symbol TEXT DEFAULT '₱', tax_rate REAL DEFAULT 0.08, receipt_tagline TEXT DEFAULT 'The loop that never breaks.', receipt_footer TEXT DEFAULT 'Thank you — come again.', order_prefix TEXT DEFAULT 'R-');
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL, sort_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, category_id INTEGER REFERENCES categories(id), name TEXT NOT NULL, price INTEGER NOT NULL, active INTEGER DEFAULT 1, stock_tracked INTEGER DEFAULT 1, stock_qty INTEGER DEFAULT 0, low_stock_threshold INTEGER DEFAULT 5, description TEXT DEFAULT '', featured INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS product_modifiers (id INTEGER PRIMARY KEY, product_id INTEGER REFERENCES products(id), modifier_name TEXT NOT NULL, price_delta INTEGER DEFAULT 0, active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, order_number TEXT UNIQUE, timestamp TEXT DEFAULT CURRENT_TIMESTAMP, status TEXT DEFAULT 'completed' CHECK(status IN ('pending','completed','voided','refunded')), subtotal INTEGER, discount_amount INTEGER DEFAULT 0, tax_amount INTEGER DEFAULT 0, total INTEGER, tendered INTEGER, change INTEGER, voided_at TEXT DEFAULT NULL, refunded_at TEXT DEFAULT NULL);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES orders(id), product_id INTEGER REFERENCES products(id), qty INTEGER DEFAULT 1, unit_price INTEGER NOT NULL, modifier_name TEXT, modifier_price_delta INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES orders(id), method TEXT DEFAULT 'cash', tendered INTEGER, change INTEGER, timestamp TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_movements (id INTEGER PRIMARY KEY, product_id INTEGER REFERENCES products(id), order_id INTEGER REFERENCES orders(id), delta INTEGER NOT NULL, reason TEXT NOT NULL DEFAULT 'sale' CHECK(reason IN ('sale','void','refund','manual')), timestamp TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events (id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES orders(id), event_type TEXT, details_json TEXT, timestamp TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS carts (id INTEGER PRIMARY KEY, session_id TEXT NOT NULL UNIQUE, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, status TEXT DEFAULT 'active' CHECK(status IN ('active','abandoned','converted')));
CREATE TABLE IF NOT EXISTS cart_items (id INTEGER PRIMARY KEY, cart_id INTEGER NOT NULL REFERENCES carts(id) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL DEFAULT 1 CHECK(qty >= 1 AND qty <= 99), added_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS voids (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), reason TEXT NOT NULL, amount INTEGER NOT NULL, processed_at TEXT DEFAULT CURRENT_TIMESTAMP, processed_by TEXT DEFAULT 'cashier');
CREATE TABLE IF NOT EXISTS refunds (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), amount INTEGER NOT NULL, reason TEXT NOT NULL, processed_at TEXT DEFAULT CURRENT_TIMESTAMP, processed_by TEXT DEFAULT 'cashier');
CREATE INDEX IF NOT EXISTS idx_orders_timestamp ON orders(timestamp);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id);
CREATE INDEX IF NOT EXISTS idx_carts_session ON carts(session_id);
CREATE INDEX IF NOT EXISTS idx_cart_items_cart ON cart_items(cart_id);
